"""Prepare only the four already-retrieved atlas ROIs. Offline; original FITS untouched."""
from pathlib import Path
import json,hashlib,argparse,os
import numpy as np
from astropy.io import fits
from PIL import Image
P=argparse.ArgumentParser();P.add_argument('--output',default=str(Path(__file__).resolve().parents[1]/'public/investigations/atlas-v1'));P.add_argument('--records',default=os.environ.get('PARALLAX_ATLAS_RECORDS',str(Path(__file__).resolve().parents[1]/'.local-data/atlas/observation-evidence.json')));args=P.parse_args();O=Path(args.output);O.mkdir(parents=True,exist_ok=True)
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def asset(p,dtype,shape,classification):return dict(path='investigations/atlas-v1/'+p.name,sha256=sha(p),byteLength=p.stat().st_size,dtype=dtype,shape=shape,classification=classification)
obs=[]
for r in sorted(json.loads(Path(args.records).read_text()),key=lambda z:z['timestamp_fits']):
 original=Path(r['path']);assert sha(original)==r['sha256']
 with fits.open(original,mode='readonly',memmap=False) as h:
  (y0,y1),(x0,x1)=r['roi_source_bounds_yx'];a=np.asarray(h['IMAGE'].data[y0:y1,x0:x1],dtype='<f4');v=np.asarray(h['VARIANCE'].data[y0:y1,x0:x1],dtype='<f4');f=np.asarray(h['FLAGS'].data[y0:y1,x0:x1],dtype='<u4')
  good=(np.isfinite(a)&np.isfinite(v)&(v>0)&((f&np.uint32(0xffffffff^(1<<21)))==0)).astype('u1');assert a.shape==(117,117)
  low,high=map(float,np.percentile(a[good==1],[2,99.5]));scaled=np.zeros(a.shape);scaled[good==1]=np.arcsinh(8*np.clip((a[good==1]-low)/(high-low),0,1))/np.arcsinh(8)
  rgba=np.zeros((*a.shape,4),dtype='u1');rgba[:,:,:3]=(scaled[:,:,None]*255).round().astype('u1');rgba[:,:,3]=good*255
  assets={}
  for key,array,dt in [('image',a,'float32'),('variance',v,'float32'),('flags',f,'uint32'),('mask',good,'uint8')]:
   path=O/(r['product_id']+'.'+key+('.u8' if key=='mask' else '.u32' if key=='flags' else '.f32'));path.write_bytes(array.tobytes());assets[key]=asset(path,dt,[117,117],'Observed' if key in ['image','variance','flags'] else 'Processed')
  path=O/(r['product_id']+'.png');Image.fromarray(rgba[::-1]).save(path);assets['preview']=asset(path,'png',[117,117],'Processed');path=O/(r['product_id']+'.hero.png');Image.fromarray(rgba[33:84,33:84][::-1]).save(path);assets['hero']=asset(path,'png',[51,51],'Processed')
  path=O/(r['product_id']+'.headers.txt');path.write_text('\n\n'.join(z.header.tostring(sep='\n') for z in h),encoding='utf-8')
  obs.append(dict(id=r['product_id'],label=r['timestamp_fits'][:10],observedAt=r['timestamp_fits']+'Z',dimensions=[117,117],source=dict(path=original.name,sha256=r['sha256'],byteLength=r['bytes'],archiveUrl=r['actual_url'],archiveProductId=r['product_id'],archiveRelease=r['release'],pipelineVersion=r['pipeline'],archiveOriginStatus=r['retrieved_kind'],priorChecksumMatch=True,digestScope=r['retrieved_kind']),units=dict(image='MJy/sr',variance='(MJy/sr)^2',flags='dimensionless'),wavelength=dict(approximateUm=r['approximate_wavelength_um'],approximateBandwidthUm=r['approximate_bandwidth_um'],classification='Unavailable or unverified',scientificCalibration=False,source='Observation WCS-WAVE at predicted position',note='Approximate native LVF response; not a calibrated equal-band comparison'),render=dict(low=low,high=high,soft=(high-low)/8,algorithm='asinh8; independent eligible2–99.5percentiles; grayscale',orientation='original detector orientation, y up; not north-up',heroBounds_yx=[[33,84],[33,84]]),assets=assets,marker=dict(type='MODEL PREDICTION',xy=r['predicted_roi_xy_zero_based'],raDec=r['predicted_radec'],source=r['coordinate_source']),quality=dict(validPixels=int(good.sum()),totalPixels=int(good.size),core=r['regions']['predicted_r2p5'],flagDefinitions=r['flag_definitions'],maskPolicy='finite IMAGE; finite positive VARIANCE; retain SOURCE21 alone; exclude every other native bit',headersPath='investigations/atlas-v1/'+path.name),lineage=dict(originalBounds_yx=r['roi_source_bounds_yx'],originalShape=r['source_dimensions_yx'],resampled=False,originalModified=False)))
 assert sha(original)==r['sha256']
m=dict(schemaVersion='parallax.attributed-investigation.v1',id='atlas-v1',title='A visitor from another star',observations=obs,measurements=dict(motion=False,brightening=False,composition=False,sourcePhotometry=False),claims=[dict(id='images',classification='DIRECTLY OBSERVED',text='Four authentic archived SPHEREx exposures; derived native ROIs and quality-selected grayscale displays.',source='https://irsa.ipac.caltech.edu/data/SPHEREx/docs/comet3iatlas/index.html'),dict(id='positions',classification='MODEL PREDICTION',text='Crosshairs mark IRSA exposure-specific predicted positions, not measured detections.',source='https://irsa.ipac.caltech.edu/data/SPHEREx/docs/comet3iatlas/obscore_3I_Atlas.vot'),dict(id='activity',classification='PUBLISHED EXTERNAL FINDING',text='NASA reports increased comet activity in December compared with August2025.',source='https://science.nasa.gov/blogs/3iatlas/2026/02/04/nasas-spherex-mission-tracks-brightening-of-interstellar-comet/',paper='https://arxiv.org/abs/2601.06759'),dict(id='boundary',classification='NOT ESTABLISHED',text='These independently stretched images do not reproduce the published photometry, motion or composition analysis.',source='https://arxiv.org/abs/2601.06759')],processing=dict(script='scripts/prepare_atlas.py',networkUsed=False,originalsModified=False,syntheticData=False),limitations=['Native grids and independent stretches; no registration, flux ratio or source localization.', 'December core includes OUTLIER exclusions; retained pixels do not reconstruct missing core flux.', 'Calibrated response equivalence and calibration UUID linkage remain unverified.'])
path=O/'manifest.json';path.write_text(json.dumps(m,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(sha(path))

